//! Static asset manifest resolution for cache busting.

use std::collections::HashMap;
use std::fs;
use std::path::Path;
use std::sync::RwLock;

/// Stores logical to hashed path mappings generated by the frontend bundler.
#[derive(Debug, Default)]
pub struct AssetManifest {
    map: RwLock<HashMap<String, String>>,
}

impl AssetManifest {
    /// Load asset manifest from a JSON file.
    #[must_use]
    pub fn from_file(path: &Path) -> Self {
        let manifest = Self::default();
        if path.exists() {
            if let Ok(content) = fs::read_to_string(path) {
                if let Ok(parsed) = serde_json::from_str::<HashMap<String, String>>(&content) {
                    *manifest.map.write().unwrap() = parsed;
                }
            }
        }
        manifest
    }

    /// Resolve a logical asset name to its public hashed URL.
    /// Falls back to unhashed `/static/...` path if not present in the manifest.
    #[must_use]
    pub fn resolve(&self, logical_name: &str) -> String {
        let map = self.map.read().unwrap();
        if let Some(hashed) = map.get(logical_name) {
            hashed.clone()
        } else if logical_name.ends_with(".css") {
            format!("/static/css/{logical_name}")
        } else if logical_name.ends_with(".js") {
            format!("/static/js/{logical_name}")
        } else {
            format!("/static/{logical_name}")
        }
    }
}
